import './../styles/article.css'
import logo from '../assets/PlancheJaune500.png'


function Article() {
    const prix = 10;
    const nom = "Planche de surf mousse 6' - 500 jaune";
    return (
        <div className="card">
            <img src={logo} alt="Planche Jaune" className="card-image"/>
            <p>{prix}€</p>
            <p>{nom}</p>
        </div>
    
    )
}
export default Article;
